document.addEventListener('DOMContentLoaded', () => {
    const productGrid = document.getElementById('productGrid');
    const searchInput = document.getElementById('searchInput');
    const modal = document.getElementById('productModal');
    const closeBtn = document.querySelector('.close-btn');

    function renderProducts(products) {
        productGrid.innerHTML = '';
        if (products.length === 0) {
            productGrid.innerHTML = `
                <div style="grid-column: 1 / -1; text-align: center; padding: 4rem 2rem; background: #fff; border-radius: 12px; border: 1px dashed #cbd5e1;">
                    <h3 style="color: #64748b; margin-bottom: 0.5rem;">sonuç bulunamadı</h3>
                    <p style="color: #94a3b8;">arama kriterlerinize uygun yedek parça bulunamadı, farklı bir terim deneyin.</p>
                </div>
            `;
            return;
        }

        products.forEach((product, index) => {
            const whatsappText = `merhaba, ${product.name} yedek parçası hakkında stok ve fiyat bilgisi almak istiyorum.`;
            const whatsappLink = `https://wa.me/905537383806?text=${encodeURIComponent(whatsappText)}`;
            const callLink = `tel:+905537383806`;

            const card = document.createElement('div');
            card.className = 'product-card';
            card.innerHTML = `
                <div class="product-image-container">
                    <img src="${product.image}" alt="${product.name}" loading="lazy" onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';">
                    <div class="product-image-placeholder" style="display:none; align-items:center; justify-content:center; height:100%; width:100%;">görsel yüklenemedi</div>
                </div>
                <div class="product-info">
                    <h3 class="product-title">${product.name}</h3>
                    <p class="product-short-desc">${product.short_desc}</p>
                    <div class="product-actions">
                        <button class="btn btn-detail" data-index="${index}">detayları gör</button>
                        <div class="product-actions-row">
                            <a href="${whatsappLink}" target="_blank" class="btn btn-whatsapp">whatsapp</a>
                            <a href="${callLink}" class="btn btn-call">ara</a>
                        </div>
                    </div>
                </div>
            `;
            productGrid.appendChild(card);
        });

        // Add event listeners to "detayları gör" buttons
        document.querySelectorAll('.btn-detail').forEach(button => {
            button.addEventListener('click', (e) => {
                const index = e.target.getAttribute('data-index');
                openModal(products[index]);
            });
        });
    }

    function openModal(product) {
        document.getElementById('modalTitle').textContent = product.name;
        document.getElementById('modalDesc').textContent = product.description;
        
        const imgEl = document.getElementById('modalImage');
        const fallback = document.getElementById('modalImageFallback');
        imgEl.style.display = 'block';
        fallback.style.display = 'none';
        imgEl.src = product.image;
        imgEl.onerror = function() {
            this.style.display = 'none';
            fallback.style.display = 'flex';
        };

        const whatsappText = `merhaba, sitede gördüğüm "${product.name}" isimli ürünle ilgileniyorum.`;
        document.getElementById('modalWhatsapp').href = `https://wa.me/905537383806?text=${encodeURIComponent(whatsappText)}`;
        document.getElementById('modalCall').href = `tel:+905537383806`;

        modal.style.display = 'block';
        document.body.style.overflow = 'hidden'; // prevent background scrolling
    }

    function closeModal() {
        modal.style.display = 'none';
        document.body.style.overflow = 'auto';
    }

    closeBtn.addEventListener('click', closeModal);
    window.addEventListener('click', (e) => {
        if (e.target === modal) closeModal();
    });

    renderProducts(productsData);

    searchInput.addEventListener('input', (e) => {
        const searchTerm = e.target.value.toLowerCase().trim();
        const filtered = productsData.filter(p => p.name.includes(searchTerm));
        renderProducts(filtered);
    });
});
